#include "dual_state_initialization.hpp"
#include "dual_state_cuda_optimizer.cuh"
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;auto cpu=initialize(c,713);uint64_t n=0;for(auto&t:schema(c)){auto&v=cpu.w.at(t.name);for(float x:v)if(!std::isfinite(x))throw std::runtime_error("initialization");n+=v.size();if(t.name.find("m.gate.bias")!=std::string::npos&&v[0]!=-2)throw std::runtime_error("gate bias");}size_t before,total,after;check(cudaMemGetInfo(&before,&total));std::vector<std::shared_ptr<Device>>arrays;for(int i=0;i<5;++i)arrays.push_back(std::make_shared<Device>(size_t(n)));check(cudaMemGetInfo(&after,&total));printf("PASS formal init params=%llu five_FP32_arrays_MiB=%.3f free_before_MiB=%.3f free_after_MiB=%.3f\n",(unsigned long long)n,double(n)*20/1048576.,double(before)/1048576,double(after)/1048576);uint64_t pertoken=0;for(auto&t:schema(c))if(t.ternary)pertoken+=t.elements();printf("WARNING tape creates per-token full weight-gradient buffers only on leaves, activations separate; graph tensor allocations and projection must be profiled, no train fit claim\n");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
